#include <errno.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>
#include <sys/random.h>
#include <sys/time.h>

#define EM_SYN56_TIMEOUT_US  1000000  //a handshake not completed within 1 s is half-open
#define EM_SYN56_SPAN_US      200000  //3 half-open handshakes of one server port within 200 ms
#define EM_SYN56_HALF_OPEN         3
#define EM_SYN56_PENDING       65536  //pool of the pending SYN-ACKs (power of 2)
#define EM_SYN56_INDEX        131072  //hash index of the pool (power of 2)
#define EM_SYN56_SERVERS        4096  //server IP address and port (power of 2)
#define EM_SYN56_PROBES            8
#define EM_SYN56_REPORT_US   1000000  //at most one alert per server port per second
#define EM_SYN56_EXPIRE_US   2000000  //a pending alert expires 2 s after it is raised
#define EM_SYN56_LANES           256  //engine instances tracked (the threads that call the rule)
#define EM_SYN56_STALL_US    2000000  //a SYN-ACK pending for more than 1 s + 2 s of the shared
                                     //clock is provisionally counted when another lane calls:
                                     //only a lane that stopped receiving packets can hold one
                                     //that long (a live lane's own 1 s expiry takes it first),
                                     //so a lane whose stream ends or pauses loses no flood, and
                                     //the skew sensitivity stays bounded to lanes more than 2 s
                                     //behind the shared clock (#68)
#define EM_SYN56_HOLD_US     8000000  //a provisionally counted entry is held for its lane to
                                     //disprove (its ACK un-counts it); past 1 s + 2 s + 8 s of
                                     //the shared clock the lane is presumed dead and the pool
                                     //entry is recycled anyway (#68)
#define EM_SYN56_DEFER_US    1000000  //a lane whose packet time did not move for this much of
                                     //the shared clock is presumed stopped: an alert raised by
                                     //provisionally counted handshakes waits for every lane that
                                     //contributed one to pass the point where it would have
                                     //adjudicated it itself — a completing ACK then already had
                                     //its chance to un-count — or to be observed frozen (#68)

enum { EM_SYN56_FREE = 0, EM_SYN56_WAITING, EM_SYN56_DONE, EM_SYN56_DRAINED };

typedef struct {
	uint32_t srv_ip, cli_ip;  //network order
	uint16_t srv_port, cli_port;
	uint32_t index;           //slot of em_syn56_index pointing at this entry
	uint32_t next;            //pool position + 1 of the next entry: the queue's, or the free list's
	uint64_t ts;              //time of the SYN-ACK, in us, on the packet clock of its queue's instance
	uint8_t  state;
} em_syn56_hs_t;

typedef struct {
	uint32_t ip;
	uint16_t port;
	uint8_t  used;
	uint8_t  count;           //half-open handshakes in ts[], at most EM_SYN56_HALF_OPEN - 1
	uint8_t  alert;           //an alert waits for the next packet to this server port
	uint8_t  reported;        //an alert of this server port was given, at reported_ts
	uint64_t ts[ EM_SYN56_HALF_OPEN - 1 ]; //SYN-ACK times of these handshakes
	uint64_t last;            //SYN-ACK time of the last half-open handshake
	uint64_t reported_ts;     //packet time of the last alert of this server port
	uint64_t alert_ts;        //packet time when the pending alert was raised
	uint64_t burst_ts;        //SYN-ACK time of the newest handshake of the last counted burst
	uint64_t prov_clear;      //packet time a lane must pass to have adjudicated the
	                          //newest provisionally counted handshake of this burst
	uint64_t prov_lanes[ (EM_SYN56_LANES + 64) / 64 ]; //lanes a provisional
	                          //count of this server came from: only they can still
	                          //disprove it — the completing ACK lands on the SYN-ACK's
	                          //lane (EM_SYN56_LANES + 1 queue positions at most)
} em_syn56_srv_t;

//one engine instance: the queue of the SYN-ACKs it has seen and not yet
//expired, ordered by its own packet time — its own packets expire them after
//1 s, or any instance's after 1 s + EM_SYN56_STALL_US of the shared clock when
//this instance stopped calling (#68)
typedef struct {
	pthread_t tid;            //the thread that drives this instance
	uint32_t  head;           //pool position + 1 of the oldest pending entry, 0: none
	uint32_t  tail;           //pool position + 1 of the newest
	uint8_t   used;
	uint8_t   unordered;      //its queue is not ordered by SYN-ACK time: a rewound
	                          //stream put older entries behind newer ones — a stale
	                          //scan cannot stop at the first fresh entry
	uint64_t  now;            //highest packet time this instance processed: past a
	                          //handshake's SYN-ACK time + 1 s, its adjudication is
	                          //over (a completing ACK had to reach it by then)
	uint64_t  mark;           //the last packet time this instance was seen at (#68)
	uint64_t  mark_now;       //the shared-clock time its packet time last moved: a
	                          //lane that did not move for EM_SYN56_DEFER_US is
	                          //presumed stopped, not owed an adjudication anymore
} em_syn56_lane_t;

static em_syn56_hs_t   em_syn56_pool[ EM_SYN56_PENDING ];
static uint32_t        em_syn56_free_head;                //pool position + 1 of a recycled entry, 0: none
static uint32_t        em_syn56_top;                      //first never-used pool position
static uint32_t        em_syn56_size;                     //entries in use, all the lanes together
static uint32_t        em_syn56_index[ EM_SYN56_INDEX ];  //pool position + 1, 0: empty
static em_syn56_srv_t  em_syn56_srv[ EM_SYN56_SERVERS ];
static uint32_t        em_syn56_alerts;                   //servers whose alert flag is set
static uint64_t        em_syn56_now;                      //highest packet time seen by any lane: the shared clock
                                                         //of the server table's alert/report rate limits (#68)
static em_syn56_lane_t em_syn56_lane[ EM_SYN56_LANES + 1 ];//the last one is the overflow lane
static pthread_mutex_t em_syn56_lock = PTHREAD_MUTEX_INITIALIZER;
static uint32_t        em_syn56_seed;                     //hash seed, drawn in on_load()

// Parses str: a decimal integer from 0 to 4294967295, without sign, leading zero or trailing character.
// Returns 1 and sets *seed when it is valid, else 0.
static int em_syn56_parse_seed( const char *str, uint32_t *seed ){
	const char *p;
	unsigned long v;
	char *end;

	for( p = str; *p >= '0' && *p <= '9'; p++ )
		;
	if( p == str || *p != '\0' || ( str[0] == '0' && str[1] != '\0' ))
		return 0;
	errno = 0;
	v = strtoul( str, &end, 10 );
	if( errno != 0 || *end != '\0' || v > UINT32_MAX )
		return 0;
	*seed = (uint32_t) v;
	return 1;
}

// Draws the hash seed of this process, or takes MMT_SEC_SYN_FLOOD_HASH_SEED (tests only).
void on_load(){
	const char *str = getenv( "MMT_SEC_SYN_FLOOD_HASH_SEED" );
	struct timespec ts;

	if( str != NULL ){
		if( em_syn56_parse_seed( str, &em_syn56_seed )){
			mmt_warn( "Rule 56: hash seed set by MMT_SEC_SYN_FLOOD_HASH_SEED (for tests only)" );
			return;
		}
		mmt_warn( "Rule 56: ignored MMT_SEC_SYN_FLOOD_HASH_SEED=\"%s\": expected a decimal integer from 0 to %lu; using a random seed",
			str, (unsigned long) UINT32_MAX );
	}
	if( getrandom( &em_syn56_seed, sizeof( em_syn56_seed ), GRND_NONBLOCK ) == sizeof( em_syn56_seed ))
		return;
	//no entropy yet (early boot): the clock and the process id
	clock_gettime( CLOCK_REALTIME, &ts );
	em_syn56_seed = (uint32_t) ts.tv_nsec ^ (uint32_t) ts.tv_sec ^ ((uint32_t) getpid() << 16);
}

//murmur3 finalizer: every input bit reaches every output bit
static inline uint32_t em_syn56_mix( uint32_t h ){
	h ^= h >> 16; h *= 0x85ebca6bu;
	h ^= h >> 13; h *= 0xc2b2ae35u;
	h ^= h >> 16;
	return h;
}

static inline uint32_t em_syn56_hash_hs( uint32_t srv_ip, uint16_t srv_port, uint32_t cli_ip, uint16_t cli_port ){
	uint32_t h = em_syn56_mix( srv_ip ^ em_syn56_seed );
	h = em_syn56_mix( h ^ cli_ip );
	return em_syn56_mix( h ^ (((uint32_t) srv_port << 16) | cli_port) );
}

//the lane of the calling thread, that is, of the engine instance it drives:
//its own queue of pending SYN-ACKs, expired by its own packet time alone —
//the fix of issue #68. A thread driving several engine instances merges them
//into the one lane of its interleaved stream; when more than EM_SYN56_LANES
//threads call, the extra ones share the overflow lane.
static em_syn56_lane_t *em_syn56_lane_of( void ){
	em_syn56_lane_t *lane;
	pthread_t self = pthread_self();
	uint64_t t = 0;
	uint32_t h, p;

	//pthread_t is opaque: fold it into 64 bits
	memcpy( &t, &self, sizeof( self ) < sizeof( t )? sizeof( self ) : sizeof( t ));
	h = em_syn56_mix( (uint32_t) t ^ (uint32_t)( t >> 32 ));
	for( p = 0; p < EM_SYN56_PROBES; p++ ){
		lane = &em_syn56_lane[ (h + p) & (EM_SYN56_LANES - 1) ];
		if( lane->used && pthread_equal( lane->tid, self ))
			return lane;
		if( !lane->used ){
			lane->used = 1;
			lane->tid  = self;
			return lane;
		}
	}
	return &em_syn56_lane[ EM_SYN56_LANES ];
}

//the pool entry that the index slot i points at, if that entry is live and owns the slot
static inline em_syn56_hs_t *em_syn56_owner( uint32_t i ){
	em_syn56_hs_t *hs;
	if( em_syn56_index[ i ] == 0 )
		return NULL;
	hs = &em_syn56_pool[ em_syn56_index[ i ] - 1 ];
	return ( hs->state != EM_SYN56_FREE && hs->index == i )? hs : NULL;
}

static em_syn56_hs_t *em_syn56_find( uint32_t srv_ip, uint16_t srv_port, uint32_t cli_ip, uint16_t cli_port ){
	uint32_t h = em_syn56_hash_hs( srv_ip, srv_port, cli_ip, cli_port ), p;
	em_syn56_hs_t *hs;
	for( p = 0; p < EM_SYN56_PROBES; p++ ){
		hs = em_syn56_owner( (h + p) & (EM_SYN56_INDEX - 1) );
		if( hs != NULL && hs->srv_ip == srv_ip && hs->cli_ip == cli_ip
				&& hs->srv_port == srv_port && hs->cli_port == cli_port )
			return hs;
	}
	return NULL;
}

static em_syn56_srv_t *em_syn56_server( uint32_t ip, uint16_t port, int create ){
	uint32_t h = em_syn56_mix( em_syn56_mix( ip ^ em_syn56_seed ) ^ port ), p;
	em_syn56_srv_t *s, *free_slot = NULL, *old = NULL;
	for( p = 0; p < EM_SYN56_PROBES; p++ ){
		s = &em_syn56_srv[ (h + p) & (EM_SYN56_SERVERS - 1) ];
		if( s->used && s->ip == ip && s->port == port )
			return s;
		if( free_slot == NULL && !s->used )
			free_slot = s;
		//the evictable server whose last half-open handshake is the oldest: no alert pending, or an
		//alert that expired (more than EM_SYN56_EXPIRE_US of the shared clock without a packet to the
		//port reporting it)
		if( s->used && ( !s->alert
				|| ( em_syn56_now > s->alert_ts && em_syn56_now - s->alert_ts > EM_SYN56_EXPIRE_US ))
				&& ( old == NULL || s->last < old->last ))
			old = s;
	}
	if( !create )
		return NULL;
	if( free_slot == NULL )
		free_slot = old;
	if( free_slot == NULL ){
		//all 8 slots have an alert still pending: replace the first one
		free_slot = &em_syn56_srv[ h & (EM_SYN56_SERVERS - 1) ];
	}
	//the pending alert of the replaced server is dropped (it expired, or all 8 slots had one)
	if( free_slot->alert )
		em_syn56_alerts --;
	memset( free_slot, 0, sizeof( *free_slot ));
	free_slot->used = 1;
	free_slot->ip   = ip;
	free_slot->port = port;
	return free_slot;
}

static inline int em_syn56_within( uint64_t a, uint64_t b ){
	return ( a > b ? a - b : b - a ) <= EM_SYN56_SPAN_US;
}

//a handshake of server ip:port, whose SYN-ACK was sent at ts, is half-open.
//provisional = the lane that owned the pending entry when the count comes
//from another lane's stall drain, NULL when the count is the owning lane's
//own expiry. Returns 0 when the count was suppressed as a repeat of an
//already-given burst, 1 when it counted.
static int em_syn56_half_open( uint32_t ip, uint16_t port, uint64_t ts,
		em_syn56_lane_t *provisional ){
	em_syn56_srv_t *s = em_syn56_server( ip, port, 1 );
	int i, n = 0, b;
	//a burst whose alert was already given does not raise a second one: a
	//flood's SYN-ACKs leave the lanes' queues in batches paced by each lane's
	//own traffic, so late expiries of the same burst (their SYN-ACK times stay
	//within 200 ms of the counted ones) would otherwise raise and report it
	//again (#68)
	if( s->reported && em_syn56_within( ts, s->burst_ts )){
		//still a half-open handshake of this server: it counts toward the
		//eviction age, only its burst count is suppressed
		if( ts > s->last )
			s->last = ts;
		return 0;
	}
	//a provisional count records the lane it was taken from — only that lane
	//can still disprove it — and the packet time past which the lane has
	//certainly adjudicated the handshake itself: an alert raised by such
	//counts waits for those lanes (EM_SYN56_DEFER_US)
	if( provisional ){
		b = provisional - em_syn56_lane;
		s->prov_lanes[ b >> 6 ] |= (uint64_t) 1 << ( b & 63 );
		if( s->prov_clear < ts + EM_SYN56_TIMEOUT_US )
			s->prov_clear = ts + EM_SYN56_TIMEOUT_US;
	}
	//keep only the half-open handshakes within 200 ms of this one
	for( i = 0; i < s->count; i++ )
		if( em_syn56_within( ts, s->ts[i] ))
			s->ts[ n++ ] = s->ts[i];
	s->count = n;
	s->last  = ts;
	if( n == EM_SYN56_HALF_OPEN - 1 ){
		s->count = 0;
		s->burst_ts = ts;
		if( !s->alert ){
			s->alert    = 1;
			s->alert_ts = em_syn56_now;
			em_syn56_alerts ++;
		}
	} else
		s->ts[ s->count++ ] = ts;
	return 1;
}

//a handshake that another lane's drain provisionally counted completed on
//its own lane after all: take the count back — the pending alert its burst
//raised is cancelled (an alert already reported cannot be), or the SYN-ACK
//time it left in the gathering count is dropped (#68)
static void em_syn56_uncount( const em_syn56_hs_t *hs ){
	em_syn56_srv_t *s = em_syn56_server( hs->srv_ip, hs->srv_port, 0 );
	int i;
	if( s == NULL )
		return;
	for( i = 0; i < s->count; i++ )
		if( s->ts[i] == hs->ts ){
			s->ts[i] = s->ts[ --s->count ];
			return;
		}
	if( s->alert && !s->reported && em_syn56_within( hs->ts, s->burst_ts )){
		s->alert = 0;
		s->prov_clear = 0;
		memset( s->prov_lanes, 0, sizeof( s->prov_lanes ));
		em_syn56_alerts --;
	}
}

//take the oldest SYN-ACK out of the lane's queue (after its 1 s on the lane's
//own packet clock, or as a dead lane's tombstone — em_syn_flood_half_open):
//still pending, it is half-open; a DRAINED one was provisionally counted by
//another lane already; then recycle the entry
static void em_syn56_pop( em_syn56_lane_t *lane ){
	uint32_t pos = lane->head - 1;
	em_syn56_hs_t *hs = &em_syn56_pool[ pos ];
	lane->head = hs->next;
	if( lane->head == 0 )
		lane->tail = 0;
	if( hs->state == EM_SYN56_WAITING )
		em_syn56_half_open( hs->srv_ip, hs->srv_port, hs->ts, NULL );
	hs->state = EM_SYN56_FREE;
	hs->next  = em_syn56_free_head;
	em_syn56_free_head = pos + 1;
	em_syn56_size --;
}

static void em_syn56_add( em_syn56_lane_t *lane, uint32_t srv_ip, uint16_t srv_port, uint32_t cli_ip, uint16_t cli_port, uint64_t now ){
	uint32_t h, p, i, pos;
	em_syn56_hs_t *hs;
	//a retransmitted SYN-ACK keeps the time of the first one
	if( em_syn56_find( srv_ip, srv_port, cli_ip, cli_port ) != NULL )
		return;
	//pool full (65536 SYN-ACKs pending): do not track this handshake. Taking out a pending one
	//before its 1 s would count a handshake that can still complete (a false alert)
	if( em_syn56_size == EM_SYN56_PENDING )
		return;
	h = em_syn56_hash_hs( srv_ip, srv_port, cli_ip, cli_port );
	for( p = 0; p < EM_SYN56_PROBES; p++ ){
		i = (h + p) & (EM_SYN56_INDEX - 1);
		if( em_syn56_owner( i ) == NULL )
			break;
	}
	//no free index slot (the index is at most half full, so this is rare): do not track this handshake
	if( p == EM_SYN56_PROBES )
		return;
	//an entry of the shared pool: the recycled free list, else a never-used
	//position (one remains, since em_syn56_size < EM_SYN56_PENDING)
	if( em_syn56_free_head != 0 ){
		pos = em_syn56_free_head - 1;
		em_syn56_free_head = em_syn56_pool[ pos ].next;
	}else
		pos = em_syn56_top ++;
	hs = &em_syn56_pool[ pos ];
	hs->srv_ip   = srv_ip;
	hs->cli_ip   = cli_ip;
	hs->srv_port = srv_port;
	hs->cli_port = cli_port;
	hs->ts       = now;
	hs->index    = i;
	hs->next     = 0;
	hs->state    = EM_SYN56_WAITING;
	em_syn56_index[ i ] = pos + 1;
	if( lane->tail != 0 ){
		em_syn56_pool[ lane->tail - 1 ].next = pos + 1;
		//a rewound stream appends an older SYN-ACK behind a newer one: the
		//queue's order is no longer the SYN-ACK times', stale entries can
		//sit anywhere in it
		if( em_syn56_pool[ lane->tail - 1 ].ts > now )
			lane->unordered = 1;
	}else
		lane->head = pos + 1;
	lane->tail = pos + 1;
	em_syn56_size ++;
}

//a lane is presumed stopped once its packet time was not seen moving for
//EM_SYN56_DEFER_US of the shared clock — refreshed on every lane scan, so the
//freeze is measured from when the lane actually stopped progressing, not from
//when a provisional count first needed it (#68)
static int em_syn56_lane_frozen( em_syn56_lane_t *l ){
	if( l->now != l->mark ){
		l->mark     = l->now;
		l->mark_now = em_syn56_now;
		return 0;
	}
	return em_syn56_now > l->mark_now
			&& em_syn56_now - l->mark_now > EM_SYN56_DEFER_US;
}

//ACK set, SYN and RST clear: the client's packet that completes (or follows) the TCP handshake
static inline int em_completes_handshake( int flags ){
	return ((flags & 0x10) != 0) && ((flags & 0x06) == 0);
}

// Called on each TCP packet. Returns 1 when this packet is to a server port that has an alert to report.
static int em_syn_flood_half_open( const void *ip_src, const void *ip_dst, double sport, double dport,
		double flags, const void *utime ){
	const struct timeval *tv = (const struct timeval *) utime;
	uint32_t src, dst;
	uint16_t sp = (uint16_t) sport, dp = (uint16_t) dport;
	int f = (int) flags, ret = 0, i;
	uint64_t now;
	uint32_t pos;
	em_syn56_hs_t *hs;
	em_syn56_srv_t *s;
	em_syn56_lane_t *lane, *l;

	if( ip_src == NULL || ip_dst == NULL || tv == NULL )
		return 0;
	memcpy( &src, ip_src, 4 );
	memcpy( &dst, ip_dst, 4 );
	now = (uint64_t) tv->tv_sec * 1000000 + (uint64_t) tv->tv_usec;

	pthread_mutex_lock( &em_syn56_lock );
	lane = em_syn56_lane_of();
	//the shared clock is the highest packet time any lane has seen: the alert
	//and report rate limits of the server table are measured on it, so a lane
	//behind in packet time cannot re-report an alert a faster lane reported,
	//nor let a pending alert expire early (#68)
	if( now > em_syn56_now )
		em_syn56_now = now;
	//how far this instance's own adjudication has run: past a handshake's
	//SYN-ACK time + 1 s it cannot disprove a provisional count of it anymore
	if( now > lane->now )
		lane->now = now;
	//the handshakes of this instance waiting for more than 1 s of its own
	//packet time (time going backwards stops this until it catches up)
	while( lane->head != 0 && now > em_syn56_pool[ lane->head - 1 ].ts
			&& now - em_syn56_pool[ lane->head - 1 ].ts > EM_SYN56_TIMEOUT_US )
		em_syn56_pop( lane );

	if( f == 0x12 ){
		if( src != dst )
			em_syn56_add( lane, src, sp, dst, dp, now );
	} else if( em_completes_handshake( f )){
		hs = em_syn56_find( dst, dp, src, sp );
		if( hs != NULL ){
			//another lane's drain provisionally counted this handshake: the
			//lane itself disproves the count now that the ACK reached it
			if( hs->state == EM_SYN56_DRAINED )
				em_syn56_uncount( hs );
			hs->state = EM_SYN56_DONE;
		}
	} else if( f & 0x04 ){
		//the client resets a pending handshake: it cannot complete, so it is half-open now
		hs = em_syn56_find( dst, dp, src, sp );
		if( hs != NULL && hs->state == EM_SYN56_WAITING ){
			hs->state = EM_SYN56_DONE;
			em_syn56_half_open( hs->srv_ip, hs->srv_port, hs->ts, NULL );
		} else if( hs != NULL && hs->state == EM_SYN56_DRAINED )
			hs->state = EM_SYN56_DONE;
	}

	//a lane that stopped calling cannot expire its queue on its own clock:
	//the calling lane provisionally counts the SYN-ACKs every lane observed
	//frozen for EM_SYN56_DEFER_US of the shared clock has held for more than
	//EM_SYN56_TIMEOUT_US + EM_SYN56_STALL_US — they become DRAINED, still on
	//their lane's queue, so a lane whose stream ends or pauses loses no flood
	//while a lane that resumes can still disprove them (its completing ACK
	//un-counts: a lagging lane keeps its own-clock verdict). A lane still
	//moving adjudicates its queue itself: its entries are never taken, only
	//stopped lanes are — the skew sensitivity of #68 stays bounded to those.
	//The calling lane's own queue stays on its own clock alone. Entries a
	//lane never adjudicates are recycled 8 s later still (#68)
	if( em_syn56_size != 0 )
		for( l = em_syn56_lane; l <= &em_syn56_lane[ EM_SYN56_LANES ]; l++ ){
			//how far each lane's own adjudication has run: a lane that keeps
			//moving owes the provisional alerts its verdict, one frozen for
			//EM_SYN56_DEFER_US is presumed stopped (#68)
			if( l->now != l->mark ){
				l->mark     = l->now;
				l->mark_now = em_syn56_now;
			}
			if( l != lane && l->head != 0 && em_syn56_lane_frozen( l )){
				//a lane still moving adjudicates its queue itself; only a lane
				//observed frozen for EM_SYN56_DEFER_US of the shared clock has
				//its stale SYN-ACKs provisionally counted here. On an ordered
				//queue the scan stops at the first fresh entry; a rewound one
				//hides stale entries behind fresh ones and is walked in full (#68)
				for( pos = l->head; pos != 0; pos = em_syn56_pool[ pos - 1 ].next ){
					hs = &em_syn56_pool[ pos - 1 ];
					if( em_syn56_now <= hs->ts
							|| em_syn56_now - hs->ts <= EM_SYN56_TIMEOUT_US + EM_SYN56_STALL_US ){
						if( l->unordered )
							continue;
						break;
					}
					if( hs->state == EM_SYN56_WAITING && em_syn56_half_open( hs->srv_ip,
							hs->srv_port, hs->ts, l ))
						hs->state = EM_SYN56_DRAINED;
				}
				//recycle at the head: tombstones the lane never adjudicated
				//(dead lanes' DRAINED entries), adjudicated handshakes whose
				//SYN-ACK aged out, and stale WAITING entries the count
				//suppressed — all older than the stale bound
				while( l->head != 0 ){
					hs = &em_syn56_pool[ l->head - 1 ];
					if( em_syn56_now <= hs->ts
							|| em_syn56_now - hs->ts <= EM_SYN56_TIMEOUT_US + EM_SYN56_STALL_US )
						break;
					if( hs->state == EM_SYN56_DRAINED
							&& em_syn56_now - hs->ts
								<= EM_SYN56_TIMEOUT_US + EM_SYN56_STALL_US + EM_SYN56_HOLD_US )
						break;
					em_syn56_pop( l );
				}
			}
		}

	//report on a packet to the server port, at most once per second of the shared clock
	if( em_syn56_alerts > 0 && src != dst ){
		s = em_syn56_server( dst, dp, 0 );
		if( s != NULL && s->alert && s->prov_clear ){
			//a provisional alert waits until every lane a count was taken
			//from has passed the point where it adjudicates the drained
			//handshake itself — a completing ACK it processed since
			//un-counted the alert already — or was observed frozen for
			//EM_SYN56_DEFER_US of the shared clock: only those lanes can
			//still disprove the count, the others' verdicts are in (#68)
			for( i = 0; i <= EM_SYN56_LANES; i++ )
				if( ( s->prov_lanes[ i >> 6 ] >> ( i & 63 ) & 1 )
						&& em_syn56_lane[ i ].now <= s->prov_clear
						&& !em_syn56_lane_frozen( &em_syn56_lane[ i ] )){
					s = NULL;
					break;
				}
		}
		if( s != NULL && s->alert &&
				( !s->reported || em_syn56_now - s->reported_ts >= EM_SYN56_REPORT_US )){
			s->alert       = 0;
			s->prov_clear  = 0;
			memset( s->prov_lanes, 0, sizeof( s->prov_lanes ));
			s->reported    = 1;
			s->reported_ts = em_syn56_now;
			em_syn56_alerts --;
			ret = 1;
		}
	}
	pthread_mutex_unlock( &em_syn56_lock );
	return ret;
}
